export const ADMIN_TRANSLATIONS = Object.fromEntries(
  languageOrder.map((language, languageIndex) => [
    language,
    Object.fromEntries(Object.entries(messageRows).map(([key, values]) => {
      const variants = typeof values === 'string' ? values.split('|') : values;
      return [key, variants[languageIndex]];
    })),
  ]),
);
